    public static TFMPageDatasources FindOrCreate(TFMPageID _pageId, TableName _tableName, TFMOrderTypes _orderType, boolean _selectforUpdate = false)
    {
        TFMPageDatasources	dataSource;
        TFMPage				page;
        dataSource.selectForUpdate(_selectforUpdate);

        select firstonly dataSource where (!_pageId || dataSource.PageID == _pageId) && dataSource.TableName == _tableName && dataSource.OrderType == _orderType;

		if (!dataSource && _pageId)
        {
            page = TFMPagesProvider::getAllPages().getPage(_pageId);

            dataSource.PageID		= _pageId;
            dataSource.TableName	= _tableName;
            dataSource.OrderType	= _orderType;
            dataSource.showImages = NoYes::Yes;
            dataSource.insert();
            if (page && page.getDataSourceBlocks().elements())
            {
                TFMPageDatasources::writeDatasourceBlocksValues(page.getDataSourceBlocks(),dataSource);
            }
        }
        return dataSource;
    }

    static protected void writeDatasourceBlocksValues(Set _dsBlocks, TFMPageDatasources	_dataSource)
    {
        SetEnumerator		sEnum = _dsBlocks.getEnumerator(), methodsEnum;
        TFMDataSourceBlock	dsBlock;
        MethodName			mName;

		while (sEnum.moveNext())
        {
            dsBlock = sEnum.current();
            methodsEnum = TFMFormLookupHelper::parmMethodsOnClass(classIdGet(dsBlock)).getEnumerator();
			while(methodsEnum.moveNext())
            {
                mName = methodsEnum.current();
                TFMGenericParms::CreateOrUpdateParameter(classId2Name(classIdGet(dsBlock)),mName,_dataSource.tableName + '/' + _dataSource.ordertype, new SysDictClass(classIdGet(dsBlock)).callObject(mName,dsBlock));
            }
        }
    }

	public Set GetDataSourceBlocks(Common _common)
    {
        TFMPage					page				= TFMPagesProvider::getAllPages().getPage(this.PageID);        
        SysDictClass			dc					= new SysDictClass(classIdGet(page));
        TFMPageTypeAttribute	pageAttr			= dc.getAttribute(classStr(TFMPageTypeAttribute));
        TFMDataSourceBlock		dsBlock;
        Set						dsBlocks			= new Set(Types::Class);
        ListEnumerator			extendingClasses	= SysExtensionAppClassFactory::getClassInstanceListFromSysAttribute(classstr(TFMDataSourceBlock),pageAttr).getEnumerator();

        while (extendingClasses.moveNext())
        {
            dsBlock = extendingClasses.current();
            dsBlock.setDataSource(this);
            SetEnumerator sEnum = TFMDataSourceBlockValuesOverride::FindOverridesForDataSourceBlock(dsBlock).getEnumerator();
            while (sEnum.moveNext())
            {
                TFMDataSourceBlockValuesOverride override = sEnum.current();
                override.modifyValuesBeforeDelta(dsBlock, _common);
            }
            TFMGenericParms::updateParmsFromOverride(classId2Name(classidget(dsBlock)),this.TableName + '/' + this.OrderType,dsBlock);
            dsBlocks.add(dsBlock);
        }
        return dsBlocks;
    }

public void initValue()
{
    this.showImages = NoYes::Yes;
    super();
}

	public str sortingKey(Common _common)
    {
        TableName		tName;
        FieldName		fName;
        MethodName		mName;
        int				pointPos = strScan(this.sortingField,'.',1,1000);
        str				retVal;
        if (!pointPos)
        {
            return '';
        }

        tName = subStr(this.SortingField,1,pointPos-1);
        fName = subStr(this.sortingField,pointPos+1,1000);
        mName = strScan(fName,'()',strLen(fName) - 4,5) ? subStr(fName,1,strLen(fName) -2 ) : '';

        retVal = TFMGenericDataHelper::findValue(_common,tName,mName ? '' : fName,mName,this.SortExpression);

        return retVal;
    }
